/** Every root token by semantic role; views read these, never literals. */
data class SemanticColors(
    val bg: Color,
    val surface: Color,
    val fg: Color,
    val muted: Color,
    val border: Color,
    val accent: Color,
    val accentHover: Color,
    val onAccent: Color,
    val cursorBg: Color,
    val noticeBg: Color,
    val error: Color,
    val errorBg: Color,
    val onError: Color,
    val focus: Color,
    val success: Color,
    val progress: Color,
)

/** Core's semantic tone as a token color. */
fun SemanticColors.tone(tone: Tone): Color = when (tone) {
    Tone.NEUTRAL -> muted
    Tone.PROGRESS -> progress
    Tone.ACCENT -> accent
    Tone.SUCCESS -> success
    Tone.DANGER -> error
}
